#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10
ENV_FILE="${ENV_FILE:-$HOME/.legnaris-vps.env}"
DEPLOY_KEY="$HOME/.ssh/legnaris_deploy"
PR_NUMBER="${PR_NUMBER:-144}"

command -v gh >/dev/null 2>&1 || { warn "install and authenticate the GitHub CLI first (gh auth login)"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh is not authenticated: run gh auth login"; exit 1; }
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
OWNER_LC=$(printf '%s' "${REPO%%/*}" | tr 'A-Z' 'a-z')
SSH_OPTS=(-o StrictHostKeyChecking=accept-new -o ConnectTimeout=10)

vps_root() { ssh "${SSH_OPTS[@]}" "${VPS_ROOT_USER}@${VPS_HOST}" "$@"; }
vps_deploy() { ssh "${SSH_OPTS[@]}" -i "$DEPLOY_KEY" -o IdentitiesOnly=yes "deploy@${VPS_HOST}" "$@"; }

banner "Legnaris: deploy to a Hostinger VPS (Docker, no Traefik)"

stage "VPS: access"
say "The wizard connects to the VPS as an admin user to prepare it."
step "Hostinger hPanel → VPS → Overview: copy the IPv4 address."
ask VPS_HOST "VPS IPv4 address:"
ask VPS_ROOT_USER "Admin SSH user (usually root):"
write_env VPS_HOST "$VPS_HOST"
write_env VPS_ROOT_USER "$VPS_ROOT_USER"
say "Testing SSH (accept the host key if asked; enter the root password/key as usual)..."
vps_root 'echo connected as $(whoami) on $(hostname)' || { warn "SSH failed: fix access and re-run"; exit 1; }
KEYSCAN=$(ssh-keyscan -t ed25519 "$VPS_HOST" 2>/dev/null)
printf '%s\n' "$KEYSCAN" | ssh-keygen -lf - || true
confirm "Does this fingerprint match the one in hPanel (or do you trust this network)?" \
  || { warn "aborting: verify the host key first"; exit 1; }
write_env VPS_KNOWN_HOSTS "$KEYSCAN"

stage "VPS: Docker, ports, deploy user and repository"
say "Checks Docker Compose >= 2.24.4, free ports 80/443, creates user 'deploy', clones the repo."
vps_root 'bash -s' <<'REMOTE'
set -euo pipefail
docker compose version
ver=$(docker compose version --short | sed 's/^v//')
[ "$(printf '%s\n2.24.4\n' "$ver" | sort -V | head -n1)" = "2.24.4" ] || { echo "Compose $ver is older than 2.24.4: upgrade docker-compose-plugin"; exit 1; }
if ss -tlnH | awk '{print $4}' | grep -Eq ':(80|443)$'; then echo "ports 80/443 are busy:"; ss -tlnp | grep -E ':(80|443)\b'; exit 1; fi
command -v git >/dev/null || { apt-get update -qq && apt-get install -y -qq git; }
id deploy >/dev/null 2>&1 || adduser --disabled-password --gecos "" deploy
usermod -aG docker deploy
install -d -o deploy -g deploy /opt/legnaris
echo "VPS base OK"
REMOTE
IS_PRIVATE=$(gh repo view "$REPO" --json isPrivate -q .isPrivate)
if [[ "$IS_PRIVATE" == "true" ]]; then
  say "The repository is private: the VPS needs a read-only deploy key to git fetch."
  vps_root "runuser -u deploy -- bash -c 'install -d -m 700 ~/.ssh; [ -f ~/.ssh/id_repo ] || ssh-keygen -q -t ed25519 -N \"\" -f ~/.ssh/id_repo; ssh-keyscan -t ed25519 github.com >> ~/.ssh/known_hosts 2>/dev/null; grep -q id_repo ~/.ssh/config 2>/dev/null || printf \"Host github.com\n  IdentityFile ~/.ssh/id_repo\n  IdentitiesOnly yes\n\" >> ~/.ssh/config'"
  REPO_PUB=$(vps_root "cat ~deploy/.ssh/id_repo.pub")
  printf '%s\n' "$REPO_PUB" | gh repo deploy-key add - --title "vps-readonly" >/dev/null 2>&1 \
    && say "deploy key registered on $REPO (read-only)" || note "deploy key already registered (or add it manually in repo Settings → Deploy keys)"
  CLONE_URL="git@github.com:${REPO}.git"
else
  CLONE_URL="https://github.com/${REPO}.git"
fi
vps_root "[ -d /opt/legnaris/.git ] || runuser -u deploy -- git clone '$CLONE_URL' /opt/legnaris"
vps_root "runuser -u deploy -- git -C /opt/legnaris remote -v | head -1"

stage "CI access: SSH key, GitHub environment and secrets"
say "Creates a dedicated key for GitHub Actions to reach the VPS as 'deploy'."
[[ -f "$DEPLOY_KEY" ]] || ssh-keygen -q -t ed25519 -N "" -C "legnaris-cd" -f "$DEPLOY_KEY"
PUB=$(cat "$DEPLOY_KEY.pub")
vps_root "runuser -u deploy -- bash -c 'install -d -m 700 ~/.ssh; touch ~/.ssh/authorized_keys; chmod 600 ~/.ssh/authorized_keys; grep -qF \"$PUB\" ~/.ssh/authorized_keys || echo \"$PUB\" >> ~/.ssh/authorized_keys'"
vps_deploy 'echo deploy user reachable with the CI key' || { warn "CI key login failed"; exit 1; }
gh api -X PUT "repos/${REPO}/environments/production" >/dev/null && say "environment 'production' ready"
set_secret VPS_HOST "$VPS_HOST"
set_secret VPS_USER "deploy"
set_secret VPS_SSH_KEY "$(cat "$DEPLOY_KEY")"
set_secret VPS_KNOWN_HOSTS "$(grep -E "^${VPS_HOST} " <<<"$VPS_KNOWN_HOSTS" || printf '%s' "$VPS_KNOWN_HOSTS")"
note "Optional manual approval gate: https://github.com/${REPO}/settings/environments → production → Required reviewers."

stage "DNS (Hostinger): api, app and ops"
say "Three A records pointing at $VPS_HOST (if the zone is on Cloudflare, keep the proxy OFF)."
open_url "https://hpanel.hostinger.com/domains"
step "Domains → paulovalleriote.io → DNS / Nameservers → DNS records → add three records:"
step "  A  api  →  $VPS_HOST "
step "  A  app  →  $VPS_HOST "
step "  A  ops  →  $VPS_HOST "
ask ACME_EMAIL "Email for Let's Encrypt expiry notices:"
write_env ACME_EMAIL "$ACME_EMAIL"
pause "Records saved? Press Enter to check propagation."
for h in api app ops; do
  got=$(getent hosts "$h.paulovalleriote.io" | awk '{print $1}' | head -n1 || true)
  if [[ "$got" == "$VPS_HOST" ]]; then say "✓ $h.paulovalleriote.io → $got"; else warn "$h.paulovalleriote.io resolves to '${got:-nothing}' (not yet $VPS_HOST); it can take a few minutes"; fi
done

stage "GitHub OAuth App (protects ops.paulovalleriote.io)"
open_url "https://github.com/settings/applications/new"
step "Application name: Legnaris"
step "Homepage URL: https://api.paulovalleriote.io"
step "Authorization callback URL: https://ops.paulovalleriote.io/oauth2/callback  (exact)"
step "Click 'Register application', then 'Generate a new client secret'."
ask GITHUB_CLIENT_ID "Client ID:"
ask_secret GITHUB_CLIENT_SECRET "Client secret:"
ask GITHUB_USER "Your GitHub username (the only one allowed into ops.):"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
write_env GITHUB_USER "$GITHUB_USER"

stage "Secrets and passwords (generated) + email provider"
say "Strong random values are generated locally; existing ones are kept on re-runs."
gen() { _existing "$1" || "${@:2}"; }
write_env JWT_SECRET "$(gen JWT_SECRET openssl rand -base64 48)"
write_env EMAIL_CODE_SECRET "$(gen EMAIL_CODE_SECRET openssl rand -base64 48)"
write_env OAUTH2_PROXY_COOKIE_SECRET "$(_existing OAUTH2_PROXY_COOKIE_SECRET || openssl rand -base64 32 | tr '+/' '-_')"
for k in MONGO_ROOT_PASSWORD MONGO_APP_PASSWORD MONGO_EXPORTER_PASSWORD MONGO_VIEW_PASSWORD \
         RABBITMQ_PASSWORD RABBITMQ_OPS_PASSWORD ME_CONFIG_BASICAUTH_PASSWORD GRAFANA_ADMIN_PASSWORD; do
  write_env "$k" "$(gen "$k" openssl rand -hex 16)"
done
write_env ME_CONFIG_BASICAUTH_USERNAME admin
write_env GRAFANA_ADMIN_USER admin
write_env API_DOMAIN api.paulovalleriote.io
write_env WEB_DOMAIN app.paulovalleriote.io
write_env OPS_DOMAIN ops.paulovalleriote.io
write_env WEB_API_BASE_URL https://api.paulovalleriote.io
write_env CORS_ALLOWED_ORIGINS https://app.paulovalleriote.io
write_env IMAGE_OWNER "$OWNER_LC"
say ""
say "Sign-in codes are emailed. With EMAIL_PROVIDER=log nothing is delivered, so real users need Resend."
if confirm "Configure Resend now?"; then
  open_url "https://resend.com/api-keys"
  step "Create an API key (sending access) and verify your sending domain under Domains."
  ask_secret RESEND_API_KEY "Resend API key:"
  ask EMAIL_FROM "From address (e.g. no-reply@paulovalleriote.io):"
  write_env EMAIL_PROVIDER resend
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  write_env EMAIL_FROM "$EMAIL_FROM"
else
  write_env EMAIL_PROVIDER log
  warn "EMAIL_PROVIDER=log: codes only appear in the worker logs (docker compose logs worker)."
fi
note "Operator console login: user 'operator', password = RABBITMQ_OPS_PASSWORD in $ENV_FILE."

stage "Upload deploy/.env to the VPS"
say "Sends the app variables (not the VPS_* wizard state) to /opt/legnaris/deploy/.env, mode 600."
FILTERED=$(mktemp)
grep -vE '^(VPS_)' "$ENV_FILE" > "$FILTERED"
scp "${SSH_OPTS[@]}" -i "$DEPLOY_KEY" -o IdentitiesOnly=yes "$FILTERED" "deploy@${VPS_HOST}:/opt/legnaris/deploy/.env"
rm -f "$FILTERED"
vps_deploy 'chmod 600 /opt/legnaris/deploy/.env && ls -l /opt/legnaris/deploy/.env'

stage "GHCR: let the VPS pull the images"
say "Images are published to ghcr.io/${OWNER_LC}/legnaris-{app,web,rabbitmq}."
say "Packages from a private repo are private by default. Pick ONE:"
step "A) Public: after the first Images run, github.com → profile → Packages → each legnaris-* → Package settings → Change visibility → Public."
step "B) Private: create a classic PAT with only read:packages (the wizard logs the VPS in)."
if confirm "Use option B (private, PAT)?"; then
  open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=legnaris-vps-pull"
  ask_secret GHCR_PAT "Paste the PAT:"
  printf '%s' "$GHCR_PAT" | vps_deploy "docker login ghcr.io -u '${REPO%%/*}' --password-stdin"
  write_env GHCR_PAT "$GHCR_PAT"
else
  note "Remember to switch the packages to Public once they exist (first Images run on main)."
fi

stage "Merge the PR and let the pipeline deploy"
say "Merging to main triggers: Images (build+scan+push) → Deploy VPS (SSH). Takes several minutes."
open_url "https://github.com/${REPO}/pull/${PR_NUMBER}"
if confirm "Merge PR #${PR_NUMBER} (squash) now?"; then
  gh pr merge "$PR_NUMBER" --repo "$REPO" --squash
else
  pause "Merge it yourself in the browser, then press Enter."
fi
open_url "https://github.com/${REPO}/actions"
step "Wait for 'Images' to finish, then 'Deploy VPS' (approve it if you added required reviewers)."
step "If you chose public packages, make them public as soon as 'Images' publishes them, before 'Deploy VPS' pulls."
pause "Press Enter when 'Deploy VPS' is green."

stage "Verify"
for u in "https://api.paulovalleriote.io/" "https://app.paulovalleriote.io/" "https://ops.paulovalleriote.io/grafana"; do
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 "$u" || true)
  say "$u → HTTP ${code:-fail}"
done
note "Expected: api and app 200 (or 404 on / for the API), ops 302 to GitHub login."
vps_deploy 'cd /opt/legnaris/deploy && docker compose ps --format "table {{.Name}}\t{{.Status}}"' || true
note "Rollback or redeploy any commit: Actions → Deploy VPS → Run workflow with the full SHA."

finish
}

run_wizard "$@"; exit
